import{_ as e,o as a,c as d,aj as r}from"./framework.js";const m=JSON.parse('{"title":"Quick Start | Documentation","description":"Take the shortest path through Kooboo: create a site, build a page, add content, write a small amount of server-side logic, and publish it.","frontmatter":{"title":"Quick Start | Documentation","description":"Take the shortest path through Kooboo: create a site, build a page, add content, write a small amount of server-side logic, and publish it.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/quick-start/index.html"}]]},"headers":[],"relativePath":"quick-start/index.md","filePath":"en/quick-start/index.md","lastUpdated":1787045655000}'),o={name:"quick-start/index.md"};function i(n,t,s,h,l,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><blockquote><p>Take the shortest path through Kooboo: create a site, build a page, add content, write a small amount of server-side logic, and publish it.</p></blockquote><h2 id="what-you-will-complete" tabindex="-1">What You Will Complete <a class="header-anchor" href="#what-you-will-complete" aria-label="Permalink to &quot;What You Will Complete&quot;">​</a></h2><p>This path is intended for administrators, implementation specialists, and developers using Kooboo for the first time. When you finish, you should have:</p><table tabindex="0"><thead><tr><th>Result</th><th>Related capability</th></tr></thead><tbody><tr><td>A site that you can open in Admin</td><td>Site list and site creation</td></tr><tr><td>A page with an accessible URL</td><td>Page, Layout, and View</td></tr><tr><td>A maintainable content collection</td><td>Content type, content folder, and content items</td></tr><tr><td>A server-side API endpoint</td><td>KScript API, CodeBlock, or API page</td></tr><tr><td>A publishable address</td><td>Basic settings, domains, and SEO</td></tr></tbody></table><h2 id="_30-minute-path" tabindex="-1">30-Minute Path <a class="header-anchor" href="#_30-minute-path" aria-label="Permalink to &quot;30-Minute Path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Order</th><th>Task</th><th>Documentation</th></tr></thead><tbody><tr><td>1</td><td>Sign in and confirm the site list, organization, and language</td><td><a href="./create-first-site.html#sign-in-and-confirm-the-entry-point">Sign in and site entry</a></td></tr><tr><td>2</td><td>Create a blank site, or begin from a template or import</td><td><a href="./create-first-site.html">Create Your First Site</a></td></tr><tr><td>3</td><td>Create a page and confirm that its URL opens</td><td><a href="./build-first-page.html">Build Your First Page</a></td></tr><tr><td>4</td><td>Create a content type and content items so the page no longer contains hard-coded data</td><td><a href="./add-content.html">Add Content</a></td></tr><tr><td>5</td><td>Bind a domain or preview the site through its system address</td><td><a href="./publish-domain.html">Publish and Domains</a></td></tr><tr><td>6</td><td>Create an API and confirm that the frontend can retrieve JSON</td><td><a href="./add-script-api.html">Write Your First KScript API</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Start in Admin before writing code</p><p>If you only want to get a site running, the first five steps do not require KScript. Open <a href="/kb-docs/api/">API Details</a> or the <a href="/kb-docs/templateEngine/">Template Engine</a> when you need scripting.</p></div><h2 id="choose-your-starting-point" tabindex="-1">Choose Your Starting Point <a class="header-anchor" href="#choose-your-starting-point" aria-label="Permalink to &quot;Choose Your Starting Point&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your current situation</th><th>Recommended entry</th></tr></thead><tbody><tr><td>You do not have a site yet</td><td><a href="./create-first-site.html">Create Your First Site</a></td></tr><tr><td>You have a site and want to edit a page</td><td><a href="./build-first-page.html">Build Your First Page</a></td></tr><tr><td>You have a page and want to connect real data</td><td><a href="./add-content.html">Add Content</a></td></tr><tr><td>You are preparing to go live</td><td><a href="./publish-domain.html">Publish and Domains</a></td></tr><tr><td>You need forms, queries, or business logic</td><td><a href="./add-script-api.html">Write Your First KScript API</a></td></tr></tbody></table><h2 id="how-this-relates-to-the-other-documentation" tabindex="-1">How This Relates to the Other Documentation <a class="header-anchor" href="#how-this-relates-to-the-other-documentation" aria-label="Permalink to &quot;How This Relates to the Other Documentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Documentation</th><th>When to read it</th></tr></thead><tbody><tr><td><a href="/kb-docs/cms/">Admin CMS</a></td><td>To find Admin menus and understand how to complete forms</td></tr><tr><td><a href="/kb-docs/templateEngine/">Template Engine</a></td><td>To understand Page, Layout, View, Script, and Style</td></tr><tr><td><a href="/kb-docs/api/">API Details</a></td><td>To look up <code>k.*</code> methods, parameters, return values, and script examples</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>After completing Quick Start, continue according to your role:</p><table tabindex="0"><thead><tr><th>Role</th><th>Next step</th></tr></thead><tbody><tr><td>Site administrator</td><td><a href="/kb-docs/cms/navigation.html">Admin CMS menu overview</a></td></tr><tr><td>Implementation specialist</td><td><a href="/kb-docs/cms/content/">Content</a> and <a href="/kb-docs/cms/site/pages.html">Pages</a></td></tr><tr><td>Frontend developer</td><td><a href="/kb-docs/templateEngine/">Template Engine</a></td></tr><tr><td>Server-side developer</td><td><a href="/kb-docs/api/getting-started/">API Getting Started</a></td></tr><tr><td>Operations or account administrator</td><td><a href="/kb-docs/cms/navigation.html">Admin CMS menu overview</a> and <a href="/kb-docs/cms/settings/">Site Settings</a></td></tr></tbody></table>',15)])])}const p=e(o,[["render",i]]);export{m as __pageData,p as default};
